def kth_largest(nums: list[int], k: int) -> int:
    """
    Find the k-th largest element in an unsorted list using the Quickselect algorithm.
    The average time complexity is O(n), while the worst case is O(n^2).
    """

    def partition(left: int, right: int, pivot_index: int) -> int:
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]  # Move pivot to end
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:  # Change comparison for k-th largest
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        nums[right], nums[store_index] = nums[store_index], nums[right]  # Move pivot to its final place
        return store_index

    def quickselect(left: int, right: int, k: int) -> int:
        if left == right:  # If the list contains only one element
            return nums[left]
        pivot_index = left + (right - left) // 2  # Choose a pivot
        pivot_index = partition(left, right, pivot_index)
        if k == pivot_index:
            return nums[k]
        elif k < pivot_index:
            return quickselect(left, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, right, k)

    return quickselect(0, len(nums) - 1, k - 1)

