def kth_largest(nums: list[int], k: int) -> int:
    """
    Find the k-th largest element in an unsorted list using the Heap-based selection algorithm.
    The time complexity is O(n + k log n).
    """

    def build_max_heap(arr: list[int]) -> None:
        length = len(arr)
        for i in range(length // 2 - 1, -1, -1):
            max_heapify(arr, length, i)

    def max_heapify(arr: list[int], n: int, i: int) -> None:
        largest = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < n and arr[left] > arr[largest]:
            largest = left
        if right < n and arr[right] > arr[largest]:
            largest = right

        if largest != i:
            arr[i], arr[largest] = arr[largest], arr[i]
            max_heapify(arr, n, largest)

    def heap_extract_max(arr: list[int]) -> int:
        if len(arr) < 1:
            raise IndexError("Heap underflow")
        max_value = arr[0]
        arr[0] = arr[-1]
        arr.pop()
        max_heapify(arr, len(arr), 0)
        return max_value

    build_max_heap(nums)

    for _ in range(k - 1):
        heap_extract_max(nums)

    return heap_extract_max(nums)
